<script setup lang="ts">import{apiErrorMessage}from'~/utils/api-error';useHead({title:'Contact'});const form=reactive({reason:'PROJECT',name:'',email:'',organization:'',phone:'',message:''});const pending=ref(false);const sent=ref(false);const errorMessage=ref('');async function submit(){pending.value=true;sent.value=false;errorMessage.value='';try{await $fetch('/api/public/contact',{method:'POST',body:form});sent.value=true;Object.assign(form,{reason:'PROJECT',name:'',email:'',organization:'',phone:'',message:''})}catch(error){errorMessage.value=apiErrorMessage(error,'Impossible d’envoyer le message.')}finally{pending.value=false}}</script>
<template><section class="section"><div class="container contact-grid"><div><p class="eyebrow">Contact</p><h1 class="display-title">Parlons de votre besoin.</h1><p class="lead">Projet, partenariat, mécénat, candidature, R&D, demande institutionnelle ou support : choisissez le motif le plus proche de votre demande.</p></div><form class="card card-pad" @submit.prevent="submit"><div v-if="sent" class="alert alert-success" role="status">Votre message a été transmis.</div><div v-if="errorMessage" class="alert alert-error" role="alert">{{errorMessage}}</div><div class="field"><label for="reason">Objet *</label><select id="reason" v-model="form.reason" class="select"><option value="PROJECT">Projet</option><option value="PARTNERSHIP">Partenariat</option><option value="SPONSORSHIP">Mécénat</option><option value="APPLICATION">Candidature</option><option value="RND">Innovation / R&D</option><option value="INSTITUTIONAL">Demande institutionnelle</option><option value="SUPPORT">Support</option><option value="OTHER">Autre</option></select></div><div class="form-grid"><div class="field"><label for="contact-name-public">Nom *</label><input id="contact-name-public" v-model="form.name" class="input" required></div><div class="field"><label for="contact-email">E-mail *</label><input id="contact-email" v-model="form.email" class="input" type="email" required></div><div class="field"><label for="contact-org">Organisation</label><input id="contact-org" v-model="form.organization" class="input"></div><div class="field"><label for="contact-phone">Téléphone</label><input id="contact-phone" v-model="form.phone" class="input" type="tel"></div><div class="field field-full"><label for="contact-message">Message *</label><textarea id="contact-message" v-model="form.message" class="textarea" minlength="10" required /></div></div><button class="btn btn-primary" type="submit" :disabled="pending">{{pending?'Envoi…':'Envoyer'}}</button></form></div></section></template>
<style scoped>.contact-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:50px;align-items:start}form{display:flex;flex-direction:column;gap:18px}@media(max-width:850px){.contact-grid{grid-template-columns:1fr}}</style>
